JordanSize.Factors.log_power.{u_2, u_3} {K : Type u_2} {V : Type u_3} [Field K] [PerfectField K] [Algebra ℚ K]
  [AddCommGroup V] [Module K V] [Module ℚ V] [IsScalarTower ℚ K V] [FiniteDimensional K V] {T : Module.End K V}
  (F : JordanSize.Factors T) (a : ℕ) : (F.power a).log = ↑a • F.log

JordanSize.jordanBound_log_iff.{u_1, u_2} {K : Type u_1} {V : Type u_2} [Field K] [Algebra ℚ K] [IsAlgClosed K]
  [AddCommGroup V] [Module K V] [Module ℚ V] [IsScalarTower ℚ K V] [FiniteDimensional K V] {T : Module.End K V}
  (F : JordanSize.Factors T) (j : ℕ) : JordanSize.JordanBound T j ↔ F.log ^ j = 0
